) AS (
  VALUES 
    (53::BIGINT, 'Excelente profe, si tiene dudas ella le explica a uno todas las veces que sea necesario. Los trabajos son un poco largos pero grupales, hágase de un buen grupo de trabajo y pasa fácil.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2026-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'aa03bb3c47b0c859d1e4413cc7340b25ede59eec334ff61d9e3b3a9a512cde39'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Es mucho más flexible que Julio, explica mejor y acompaña con mucha práctica, los exámenes si son un poco complicados y casi nunca responde el correo. Pero ella es mucho más clara cuando explica.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-17T00:00:00+00:00'::TIMESTAMPTZ, 'bcd7c51b20f2312cff845b514a521385c59551900db3433b713f40c8813faacb'::TEXT, ARRAY[1892]::BIGINT[]),
    (53::BIGINT, 'La profe es muy buena, pero las clases importantes (R) las pone asincrónicas y eso hace que uno se pierda muy fácil, pero es la mejor profe de estadística.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2025-11-05T00:00:00+00:00'::TIMESTAMPTZ, '8e0e35637515faff9914ccfd2e4284b17ddf22e39fcf15211174bdd490ce5ab4'::TEXT, ARRAY[1892]::BIGINT[]),
    (53::BIGINT, 'La profe es la mejor y siempre explica super bien y ante cualquier duda siempre siempre te ayuda'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-09T00:00:00+00:00'::TIMESTAMPTZ, '91d36d3ccc9d634491b11be91e253018670af54664f8d652ee615a55c7b66103'::TEXT, ARRAY[2471]::BIGINT[]),
    (53::BIGINT, 'muy buena profe, siempre dispuesta a ayudar y que uno comprenda la materia'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, '5d0fc74c2880f3e0a15e6d4790fd6a0ce8a6c46bbc8fc1034dddc207269128da'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'La profe es muy buena, el problema quizás es la materia que es bastante dura. Ella siempre va a estar dispuesta a explicarte las veces que lo necesites y hace los exámenes en R con códigos que ella facilita. La verdad mi experiencia con ella no fue mala, es muy dulce, solo no me gustó la materia'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Brinda apoyo']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, '8b8abd6e15c283aa18ba81b2284a89fa58ee57a162fcd56911a67e84facabdfb'::TEXT, ARRAY[1892]::BIGINT[]),
    (53::BIGINT, 'Una buena profe, las clases pueden ser aburridas, pero es más por la materia. Siempre atendía las dudas de todos.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-11T00:00:00+00:00'::TIMESTAMPTZ, '59611b4eae97c8bf18d625c04db9467b379f1decfebb00e8b2d8452485a461a7'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'La profe es super clara para explicar y se devuelve si hay dudas. Al usar R ayuda mucho al estudiante y da los scripts con las formulas en los examenes entonces no hay que aprenderselos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, '71318113ff12b948db669183eb70ad654b1d8bfc449ebdd3bba844ffb47b80e9'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Lamentablemente, mi experiencia en su clase no fue positiva debido a su evidente favoritismo hacia ciertos alumnos. Observé con frecuencia cómo la profesora dedicaba más tiempo y atención a un grupo reducido de estudiantes, mientras que ignoraba o minimizaba las preguntas y aportes de otros.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('35','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2024-02-05T00:00:00+00:00'::TIMESTAMPTZ, '20fff979d6f1ca216167b82564c74659e3c80089cd945fab7ab47ea52dcdcc3b'::TEXT, ARRAY[1892]::BIGINT[]),
    (53::BIGINT, 'Muy ordenada, los videos que sube son muy buenos la clase funciona así, ella deja el video explicativo para que lo veas antes de llegar a la clase y que ella lo explique, este modelo es bueno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-13T00:00:00+00:00'::TIMESTAMPTZ, 'db33a81b56138eef3d5c02274ed2dcf4e9f3422fe9ee0a392d452e127b76fb57'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Es una profesora que ayuda a su grupito solamente. Hace diferencia entre los que llevan Estadísticas I con ella y los que no. Con la historia de “clase invertida” no da lección. Uno tiene que ver un video y en clase presencial solo aclara dudas puntuales. Cómo eso puede llamarse clase PRESENCIAL?'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '29e42e74c08fee3a5cd03c7e8eff562814205d8671edbbf15a1d491617de7188'::TEXT, ARRAY[1892]::BIGINT[]),
    (53::BIGINT, 'En mi opinión es la mejor profe de AE, Estadística I virtual, es buena, un pco magistral al inicio pero ya con los ejemplos se entiende, haga las prácticas o no va a entender. Estadística II presencial ha sido la mejor clase que he tenido, la profe es un amor y explica cuantas veces sea necesario'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2022-12-23T00:00:00+00:00'::TIMESTAMPTZ, 'a22feb31915e7585f8162b18cbc28ccc03d167b5df22ec06a24ecf05018e9a18'::TEXT, ARRAY[2374, 1892, 1516]::BIGINT[]),
    (53::BIGINT, 'La profe es muy pasiva, una belleza de persona, puede explicar una y otra vez si usted no entiende. Le recomiendo que vaya haciendo las prácticas en clase junto con ella y así no se pierde y el curso lo pasa fácil. Ella es muy accesible!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Brinda apoyo']::TEXT[], '2022-06-30T00:00:00+00:00'::TIMESTAMPTZ, '568e9c200a06d728b8a5b23315384f1eeff9dfc50269deb1d5a3d2849e384357'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Pese a que la profesora puede llegar a ser flexible, es repetitiva con lo que dice en vez de ir al grano, haciendo que el estudiante se confunda y la clase sea por lo tanto larga, no recomendaría llevar con ella al menos Estadística I'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'f0afffb216243ec3241c5aa6544b73376d7ac96d0367844c9cdfdd822d7cb63a'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Es muy buena profe, es muy flexible, y las asignaciones se pasan bien si pones bastante atención, para mí la mejor'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '02a94e40141c4be61696e1e629465acc2684c3cbb9664de85012797e22ca898c'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Excelente profesora, explica muy bien, es importante poner atención y tomar los apuntes necesarios. Dura mucho en dar las notas y a veces las instrucciones no son lo suficientemente claras.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Brinda apoyo']::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'e761bdc1dd4c24463e03520d352a0be9a4afad12c536bb3b2654c957ec4cd4c1'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Excelente profesora y atiende con las dudas de los estudiantes. Poner bastante atención en las clases y con eso entiende la materia. Solo que dura un poco en dar las notas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'c256e0c9a250abd4e5a00936b6985f7123d0f3ab6b9676e209ddd98c32a81109'::TEXT, ARRAY[1892]::BIGINT[]),
    (53::BIGINT, 'La profe es muy buena gente, atenta y sabe escuchar. Las clases duran máximo 2 horas y siempre explica muy bien. Le recomiendo que vaya haciendo las prácticas con ella. Los trabajos son en grupo y no requieren mucho tiempo pero si es necesario entender bien la materia. Los exámenes son individuales.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'f9097276c8c99273ba7fcfcf0c79c5c651129f63a769a8fdffcb82f451a56d10'::TEXT, ARRAY[1892]::BIGINT[]),
    (53::BIGINT, 'Excelente profesora, aunque deja varios videos por lo uno se pierde. Las tareas y extra clases se hace en grupo, consiga un buen equipo de trabajo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases largas']::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'ca1298f9bca70159f6032056e1b654dac909a873228ce5ae1c62a630091e6771'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Excelente persona, trata de explicar lo mas claro posible, escucha y atiende a los estudiantes. Las clases son largas y muy cargadas por que imparte clases sincrónicas y asincrónicas juntas en cada clase y la carga asincrónica es mucha para algo podría explicar en 5 minutos yendo al grano.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2021-07-07T00:00:00+00:00'::TIMESTAMPTZ, 'c84589e82ae3c54822dc2be183f917d553702e6578b59fb85196012e3af69e1c'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'La profe sabe de lo que habla. En modalidad virtual sólo deja videos y hace una que otra clase pases be dudas. Los exámenes son un poco difíciles pero si lleva la materia al día se pasa bien. Tenga un buen grupo de trabajo. La recomiendo, es muy paciente y ayuda cuando se lo piden'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'fd154c6b6fd9e19acd8f74367a887763e8fe3ebbfd8044e00323db4dffb8a2f4'::TEXT, ARRAY[1892]::BIGINT[]),
    (53::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, 'f19ea89e8db5051b204834b167fd60203bc50cb22628647b9dcc254db250a74e'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Es muy buena explicando y tiene mucha paciencia en esta modalidad virtual solo deja videos explicando la materia no da clases, califica un poco duro pero se pasa'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Brinda apoyo']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '401d0794248bdced9911e0477164825520a41e418d4f7bd1c32ddc71e0996281'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Explica muy bien, es muy paciente y brinda ayuda. Asigna muchas tareas, quices, extraclases y proyectos, pero hace que sus clases sean fáciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2020-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'df4907fcde896b09ec7bf6db84607573d179e475359228362e50fb0506edd547'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Es una excelente profesora, deja mucha práctica y siempre trata a de ayudar al estudiante, es muy buena explicando.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2020-01-18T00:00:00+00:00'::TIMESTAMPTZ, '8bdf2aa4e2f4c7e5cea05ca835bc4dc5d3955f80f8482a4f219f56afd1905d2b'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Ella es una persona agradable, paciente si usted tiene dudas, pero califica muy duro, da la materia muy rápido y cuesta un poco seguirle ritmo, con mucho esfuerzo se pasa, casi todo hace en la compu.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2019-06-28T00:00:00+00:00'::TIMESTAMPTZ, '0a04fa05994cecae6d5876a6105f53630f4a8c170abeefe1635ecb443b5a3c27'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Súper buena profesora, explica muy bien. Siempre aclara dudas, califica un poco duro pero se pasa bien. Ponga atención en clase y va súper bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'db6ba3e7319a95861c1ad10ea8bb1e2e5b39ebc3e65f1329eca003878f09fd47'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Es una persona muy amable, agradable PACIENTE. Explica muy bien pero se debe estudiar porque los exámenes son algo difíciles. Ella ayuda al que lo necesite, el curso es completamente pasable para el que se mantiene al día. Cuidado con el proyecto así que pregunté todo lo que pueda. Muy recomendada.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'e08395c0df8c9595ffa08f2868c8319fc0c223d3f39be536b5e2b71b71e04aba'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Excelente profesora. Califica muy duro y en los exámenes mete ejercicios que no vemos en clase. El curso es pasable con ella, solo se debe estar al día con la materia.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2019-06-13T00:00:00+00:00'::TIMESTAMPTZ, '737967796d24b5835db85e4c728a5781d9bd2cac121bedf9162926e9dec058e5'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Excelente persona, muy amable, súper atenta y paciente. Siempre ayuda bastante, pero califica muy rudo y los exámenes son un poco difíciles. Igual es pasable.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'a4a37876930a0285a3593fd353527f78e125fb4bba3deeca7c1570347a6d195f'::TEXT, ARRAY[1892]::BIGINT[]),
    (53::BIGINT, 'Es buena profe, explica bien y ayuda, califica rudo pero se pasa con esfuerzo'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-25T00:00:00+00:00'::TIMESTAMPTZ, '96df4385023b289ef90bbb32aea185ae08a59a3516fe13ae8d1228986a6b1838'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Es super buena profe, se le entiende super bien y explica bien, es buena gente pero si califica un poco duro pero se pasas bien.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-24T00:00:00+00:00'::TIMESTAMPTZ, '91832c283442af4ec76953756a86f119eec657b5cf4be2c4015218c1745e5a87'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'De las mejores profes que he tenido. Demasiado buena gente y vacilona. Explica súper bien y atiende todas las dudas siempre con mucha paciencia y dedicación. El curso se vuelve muy fácil con ella :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, '72c3c20f6632793224f644b260c7018efd79eadddcb1ef274b8d6d97ab6c40fa'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Excelente persona. Dedica todo el tiempo necesario para asegurarse de que los estudiantes comprendan. Tiene muchísima paciencia.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'd34b8da69606f02ecb5099694588d0236c28e3dda4eec20aec6f25d1c5070cb0'::TEXT, ARRAY[2374]::BIGINT[]),
    (53::BIGINT, 'Es una buena profesora aunque califica un poco duro.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'c9977909fa19d0d26e85e9fac652a51c3b59dd673e6090c104dbfe49a4ea680a'::TEXT, ARRAY[2374]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
